old_thread = s[s.index("/**\n * The whole thread for one issue"):s.index("export async function countComments")]
new_thread = '''/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply beneath it — direct or through other
 * replies — in order of posting. A deleted comment stays in place as a
 * placeholder (marked by `archivedAt`, text removed) so the replies under it
 * keep their anchor.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) =>
    redactIfDeleted({ ...toComment(row.comment), author: toUser(row.author) }),
  );

  const position = new Map(decorated.map((comment, index) => [comment.id, index]));
  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: descendantsOf(comment.id, repliesBy).sort(
        (a, b) => (position.get(a.id) ?? 0) - (position.get(b.id) ?? 0),
      ),
    }));
}

/** Every comment beneath `rootId` in the reply tree, however deep. */
function descendantsOf(
  rootId: string,
  repliesBy: ReadonlyMap<string, readonly CommentWithAuthor[]>,
): CommentWithAuthor[] {
  const found: CommentWithAuthor[] = [];
  const pending = [...(repliesBy.get(rootId) ?? [])];
  while (pending.length > 0) {
    const next = pending.pop();
    if (next === undefined) break;
    found.push(next);
    pending.push(...(repliesBy.get(next.id) ?? []));
  }
  return found;
}

/** A deleted comment keeps its identity and place but loses its text. */
function redactIfDeleted(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "", mentionedUserIds: [] };
}

'''
s = s.replace(old_thread, new_thread)

old_update = '''/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })'''
new_update = '''/**
 * An edit stamps `edited_at`, which the UI shows next to the timestamp, and
 * replaces the recorded mentions with the ones the new body makes.
 */
export async function updateComment(
  input: UpdateCommentInput,
  mentionedUserIds: readonly UserId[],
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({
      body: input.body,
      mentionedUserIds: JSON.stringify(mentionedUserIds),
      editedAt: stamp,
      updatedAt: stamp,
    })'''
assert s.count(old_update) == 1
s = s.replace(old_update, new_update)
open(p, "w").write(s)
EOF
